1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.util.UUID;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	
11	/**
12	 * Assigns a shared {@code householdId} when a create-owner request opts in with
13	 * {@code sharesHousehold} and an existing owner shares its household: same last name
14	 * (compared case-insensitively with runs of whitespace collapsed to a single space) and
15	 * same address (compared in the normalized form of {@link AddressNormalizer}). Both the new owner and
16	 * every existing household member are assigned the same identifier, derived deterministically
17	 * from the normalized last name and address, so members always agree on it and it never
18	 * changes as more join.
19	 *
20	 * <p>Runs after {@link BuildOwner} (so the Owner exists) and within the create transaction
21	 * (so any backfilled members commit with the new owner). When {@code sharesHousehold} is not
22	 * set, or no existing owner shares the household, no id is assigned.
23	 */
24	public class AssignHousehold {
25	
26	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
27	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
28	            return;
29	        }
30	        String lastName = normalize(owner.getLastName());
31	        String address = AddressNormalizer.normalize(owner.getAddress());
32	        String householdId = householdId(lastName, address);
33	        boolean shared = false;
34	        for (Owner existing : ownerRepository.findAll()) {
35	            if (normalize(existing.getLastName()).equals(lastName)
36	                    && AddressNormalizer.normalize(existing.getAddress()).equals(address)) {
37	                shared = true;
38	                if (!householdId.equals(existing.getHouseholdId())) {
39	                    existing.setHouseholdId(householdId);
40	                    ownerRepository.save(existing);
41	                }
42	            }
43	        }
44	        if (shared) {
45	            owner.setHouseholdId(householdId);
46	        }
47	    }
48	
49	    private static String householdId(String lastName, String address) {
50	        byte[] key = (lastName + "\n" + address).getBytes(StandardCharsets.UTF_8);
51	        return UUID.nameUUIDFromBytes(key).toString();
52	    }
53	
54	    private static String normalize(String value) {
55	        if (value == null) {
56	            return "";
57	        }
58	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
59	    }
60	}
