1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Flags a create-owner request as a <em>possible</em> (soft) duplicate: one that is not a hard
11	 * duplicate (see {@link RejectDuplicateIdentity}) yet shares an existing owner's
12	 * {@code lastName} (compared case-insensitively with surrounding whitespace trimmed) and
13	 * {@code postcode} while carrying a <em>different</em> telephone (compared in E.164 form, see
14	 * {@link E164Telephone}). Such an owner is still created; it is merely marked so callers can
15	 * review it. When a match is found the owner's {@code possibleDuplicate} is set true and
16	 * {@code possibleDuplicateOf} to the matching owner's id (the earliest such owner by id when
17	 * several match); otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf}
18	 * is left unset.
19	 *
20	 * <p>Runs after {@link RejectDuplicateIdentity} (so a hard duplicate has already been rejected)
21	 * and within the create transaction, but before {@link SaveOwner}, so the new owner is not yet
22	 * persisted and cannot match itself.
23	 */
24	public class AssignPossibleDuplicate {
25	
26	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
27	        owner.setPossibleDuplicate(false);
28	        String lastName = normalize(owner.getLastName());
29	        String postcode = normalize(owner.getPostcode());
30	        if (postcode.isEmpty()) {
31	            return; // no postcode to share on
32	        }
33	        String telephone = E164Telephone.normalizeOrNull(owner.getTelephone());
34	        Integer matchId = null;
35	        for (Owner existing : ownerRepository.findAll()) {
36	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
37	                continue;
38	            }
39	            if (!normalize(existing.getLastName()).equals(lastName)) {
40	                continue;
41	            }
42	            if (!normalize(existing.getPostcode()).equals(postcode)) {
43	                continue;
44	            }
45	            String existingTelephone = E164Telephone.normalizeOrNull(existing.getTelephone());
46	            if (java.util.Objects.equals(telephone, existingTelephone)) {
47	                continue; // same telephone is not a soft match (it would be a hard duplicate)
48	            }
49	            if (matchId == null || existing.getId() < matchId) {
50	                matchId = existing.getId();
51	            }
52	        }
53	        if (matchId != null) {
54	            owner.setPossibleDuplicate(true);
55	            owner.setPossibleDuplicateOf(matchId);
56	        }
57	    }
58	
59	    private static String normalize(String value) {
60	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
61	    }
62	}
