1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Rejects a create-owner request whose {@code identityKey} (see {@link OwnerIdentity}) equals
10	 * an existing owner's. This is the single, consolidated duplicate check: the former separate
11	 * telephone, email and household checks are now expressed through this one key. A collision is
12	 * rejected 409 via {@link DuplicateIdentityException}.
13	 *
14	 * <p>Runs after {@link AssignHousehold} (so the new owner's {@code householdId} — and any
15	 * household members it just backfilled — are set) and within the create transaction, but
16	 * before {@link SaveOwner}, so the new owner is not yet persisted and cannot collide with
17	 * itself. Because the telephone is part of the key, two members of the same household with
18	 * different telephones have different keys and are both allowed; only an exact full-key match
19	 * is a duplicate.
20	 */
21	public class RejectDuplicateIdentity {
22	
23	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
24	            throws DuplicateIdentityException {
25	        String identityKey = OwnerIdentity.key(owner);
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
28	                continue;
29	            }
30	            if (identityKey.equals(OwnerIdentity.key(existing))) {
31	                throw new DuplicateIdentityException(
32	                        "Another owner with the same identity already exists");
33	            }
34	        }
35	    }
36	}
