16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
22	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
23	    @Mapping(target = "membershipNumber", expression = "java(toMembershipNumber(owner))")
24	    @Mapping(target = "checkDigit", expression = "java(toCheckDigit(owner))")
25	    @Mapping(target = "membershipLevel", expression = "java(toMembershipLevel(owner))")
26	    @Mapping(target = "locality", expression = "java(toLocality(owner))")
27	    @Mapping(target = "contactPreference", expression = "java(toContactPreference(owner))")
28	    @Mapping(target = "identityKey", expression = "java(toIdentityKey(owner))")
29	    @Mapping(target = "ageBand", expression = "java(toAgeBand(owner))")
30	    OwnerDto toOwnerDto(Owner owner);
31	
32	    /**
33	     * Derives the owner's {@code ageBand} from its {@code birthDate} measured against its
34	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64,
35	     * {@code SENIOR} at 65 or older. Returns null when either date is absent (so no band is
36	     * reported for owners with no supplied birth date).
37	     */
38	    default org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
39	        java.time.LocalDate birthDate = owner.getBirthDate();
40	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
41	        if (birthDate == null || registrationDate == null) {
42	            return null;
43	        }
44	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
45	        if (age < 18) {
46	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.MINOR;
47	        }
48	        if (age < 65) {
49	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.ADULT;
50	        }
51	        return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.SENIOR;
52	    }
53	
54	    /**
55	     * Derives the owner's {@code identityKey}: the single value that consolidates all
56	     * duplicate detection, {@code normalizedTelephone + '|' + (email or empty) + '|' +
57	     * (householdId or empty)}.
58	     */
59	    default String toIdentityKey(Owner owner) {
60	        return org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(owner);
61	    }
62	
63	    /**
64	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email is present,
65	     * otherwise {@code PHONE}.
66	     */
67	    default String toContactPreference(Owner owner) {
68	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
69	        return hasEmail ? "EMAIL" : "PHONE";
70	    }
71	
72	    /**
73	     * Derives the owner's locality (region) from its region-and-hash identity: the
74	     * {@code customerCode} is {@code <REGION>-<HASH8>}, so the locality is the REGION segment
75	     * preceding the hash. Falls back to deriving the region directly from the postcode/city
76	     * (see {@link org.springframework.samples.petclinic.rest.function.owner.OwnerCustomerCode})
77	     * only for unmigrated owners that carry no customer code.
78	     */
79	    default String toLocality(Owner owner) {
80	        String customerCode = owner.getCustomerCode();
81	        if (customerCode != null) {
82	            int dash = customerCode.indexOf('-');
83	            if (dash > 0) {
84	                return customerCode.substring(0, dash);
85	            }
86	        }
87	        return org.springframework.samples.petclinic.rest.function.owner.OwnerCustomerCode
88	                .region(owner.getPostcode(), owner.getCity());
89	    }
90	
91	    /**
92	     * Derives the owner's numeric membership level (1 to 3), computed on creation: start at 1;
93	     * add 1 when an email is present; add 1 when the owner has no namesakes ({@code namesakeCount}
94	     * is 0); capped at 3 (level 4 is reserved for tenure).
95	     */
96	    default Integer toMembershipLevel(Owner owner) {
97	        int level = 1;
98	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
99	        if (hasEmail) {
100	            level++;
101	        }
102	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
103	        if (unique) {
104	            level++;
105	        }
106	        return Math.min(level, 3);
107	    }
108	
109	    /**
110	     * Derives the owner's membership number as {@code <customerCode>-M<YY>}, where YY is the
111	     * last two digits of the registration-date year (e.g. {@code NSW-1A2B3C4D-M26}). Returns
112	     * null when either the customer code or registration date is absent (e.g. unmigrated seed
113	     * data).
114	     */
115	    default String toMembershipNumber(Owner owner) {
116	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
117	            return null;
118	        }
119	        return owner.getCustomerCode() + "-M" + String.format("%02d", owner.getRegistrationDate().getYear() % 100);
120	    }
121	
122	    /**
123	     * Derives the owner's {@code checkDigit}: the Luhn check digit (0-9) computed over the
124	     * digits contained in the {@code customerCode}. Returns null when the customer code is
125	     * absent (e.g. unmigrated seed data).
126	     */
127	    default Integer toCheckDigit(Owner owner) {
128	        String customerCode = owner.getCustomerCode();
129	        if (customerCode == null) {
130	            return null;
131	        }
132	        int sum = 0;
133	        boolean dbl = true;
134	        for (int i = customerCode.length() - 1; i >= 0; i--) {
135	            char c = customerCode.charAt(i);
136	            if (c < '0' || c > '9') {
137	                continue;
138	            }
139	            int d = c - '0';
140	            if (dbl) {
141	                d *= 2;
142	                if (d > 9) {
143	                    d -= 9;
144	                }
145	            }
146	            sum += d;
147	            dbl = !dbl;
148	        }
149	        return (10 - (sum % 10)) % 10;
150	    }
151	
152	    Owner toOwner(OwnerDto ownerDto);
153	
154	    @Mapping(target = "id", ignore = true)
155	    @Mapping(target = "pets", ignore = true)
156	    @Mapping(target = "customerCode", ignore = true)
157	    @Mapping(target = "householdId", ignore = true)
158	    @Mapping(target = "namesakeCount", ignore = true)
159	    @Mapping(target = "householdSize", ignore = true)
160	    @Mapping(target = "possibleDuplicate", ignore = true)
161	    @Mapping(target = "possibleDuplicateOf", ignore = true)
162	    Owner toOwner(OwnerFieldsDto ownerDto);
163	
164	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
165	
166	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
167	
168	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
169	        OwnerPageDto ownerPageDto = new OwnerPageDto();
170	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
171	        ownerPageDto.setPage(ownerPage.getNumber());
172	        ownerPageDto.setSize(ownerPage.getSize());
173	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
174	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
175	        return ownerPageDto;
176	    }
177	}
